// Runs on 'init' (priority 0) so old redirect rules from the one-page site cannot hijack these URLs
add_action('init', function () {
    if (is_admin() || (defined('DOING_AJAX') && DOING_AJAX) || (defined('REST_REQUEST') && REST_REQUEST)) return;
    if (!in_array($_SERVER['REQUEST_METHOD'] ?? 'GET', array('GET', 'HEAD'), true)) return;
    $routes = [
        '/about/' => 'about.html',
        '/affiliate-program/' => 'affiliate-program.html',
        '/ai-agents/' => 'ai-agents.html',
        '/ai-chatbot-development/' => 'ai-chatbot-development.html',
        '/ai-employees/' => 'ai-employees.html',
        '/ai-agents/ecommerce/' => 'ai-agents-ecommerce.html',
        '/client-dashboard/' => 'client-dashboard.html',
        '/contact/' => 'contact.html',
        '/faqs/' => 'faqs.html',
        '/' => 'home.html',
        '/ai-agents/real-estate/' => 'ai-agents-real-estate.html',
        '/ai-agents/car-rental/' => 'ai-agents-car-rental.html',
        '/refund-policy/' => 'refund-policy.html',
        '/privacy-policy/' => 'privacy-policy.html',
        '/ai-agents/personal-assistant/' => 'ai-agents-personal-assistant.html',
        '/ai-agents/health-fitness/' => 'ai-agents-health-fitness.html',
        '/ai-agents/hospitality/' => 'ai-agents-hospitality.html',
        '/pricing/' => 'pricing.html',
        '/ai-agents/ai-calling-agent/' => 'ai-agents-ai-calling-agent.html',
        '/thanks/' => 'thanks.html',
        '/whatsapp-automation/' => 'whatsapp-automation.html',
        '/ar/about/' => 'ar-about.html',
        '/ar/affiliate-program/' => 'ar-affiliate-program.html',
        '/ar/ai-agents/' => 'ar-ai-agents.html',
        '/ar/ai-chatbot-development/' => 'ar-ai-chatbot-development.html',
        '/ar/ai-employees/' => 'ar-ai-employees.html',
        '/ar/ai-agents/ecommerce/' => 'ar-ai-agents-ecommerce.html',
        '/ar/client-dashboard/' => 'ar-client-dashboard.html',
        '/ar/contact/' => 'ar-contact.html',
        '/ar/faqs/' => 'ar-faqs.html',
        '/ar/' => 'ar.html',
        '/ar/ai-agents/real-estate/' => 'ar-ai-agents-real-estate.html',
        '/ar/ai-agents/car-rental/' => 'ar-ai-agents-car-rental.html',
        '/ar/refund-policy/' => 'ar-refund-policy.html',
        '/ar/privacy-policy/' => 'ar-privacy-policy.html',
        '/ar/ai-agents/personal-assistant/' => 'ar-ai-agents-personal-assistant.html',
        '/ar/ai-agents/health-fitness/' => 'ar-ai-agents-health-fitness.html',
        '/ar/ai-agents/hospitality/' => 'ar-ai-agents-hospitality.html',
        '/ar/pricing/' => 'ar-pricing.html',
        '/ar/ai-agents/ai-calling-agent/' => 'ar-ai-agents-ai-calling-agent.html',
        '/ar/thanks/' => 'ar-thanks.html',
        '/ar/whatsapp-automation/' => 'ar-whatsapp-automation.html',
        '/dp-sitemap.xml' => 'dp-sitemap.xml',
    ];
    $path = parse_url($_SERVER['REQUEST_URI'], PHP_URL_PATH);
    if (!$path) return;
    // /ai-agents/real-estate  ->  301 to  /ai-agents/real-estate/
    if (substr($path, -1) !== '/' && isset($routes[$path . '/'])) {
        $qs = isset($_SERVER['QUERY_STRING']) && $_SERVER['QUERY_STRING'] !== '' ? '?' . $_SERVER['QUERY_STRING'] : '';
        wp_redirect(home_url($path . '/') . $qs, 301);
        exit;
    }
    if (!isset($routes[$path])) return;
    // leave WordPress search, previews and admin-style query URLs alone
    foreach (array('s', 'p', 'page_id', 'preview', 'post_type', 'feed') as $q) { if (isset($_GET[$q])) return; }
    $file = __DIR__ . '/dp-pages/' . $routes[$path];
    if (!is_readable($file)) return;
    global $wp_query;
    if ($wp_query) { $wp_query->is_404 = false; }
    status_header(200);
    $xml = substr($file, -4) === '.xml';
    header('Content-Type: ' . ($xml ? 'application/xml' : 'text/html') . '; charset=UTF-8');
    readfile($file);
    exit;
}, 0);
// WordPress-rendered pages (AI News blog, posts, tools): swap the theme header/footer for the DigiPromise ones
add_action('wp_head', function () {
    if (is_admin()) return;
    $f = __DIR__ . '/dp-pages/wp-chrome-head.html';
    if (is_readable($f)) readfile($f);
}, 99);
add_action('wp_footer', function () {
